CREATE TABLE public.project_secrets (project_id text NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, owner_id uuid NOT NULL, name text NOT NULL CHECK (name ~ '^[A-Z][A-Z0-9_]{0,127}$'), encrypted_value text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (project_id, name)); GRANT ALL ON public.project_secrets TO service_role; REVOKE ALL ON public.project_secrets FROM anon, authenticated; ALTER TABLE public.project_secrets ENABLE ROW LEVEL SECURITY; CREATE INDEX project_secrets_owner_idx ON public.project_secrets(owner_id);